groups = {}
def group(id, name, short, why, photo):
    groups[id] = dict(id=id, name=tr(*name), short=tr(*short), why=tr(*why), photo=photo)
group('web', ['Websites','Websites','Sitios web','Sites web','المواقع الإلكترونية','Web stranice'],
 ['Online überzeugen. Anfragen erhalten.','Present your business. Receive inquiries.','Presenta tu negocio. Recibe consultas.','Présentez votre entreprise. Recevez des demandes.','اعرض نشاطك واستقبل الطلبات.','Predstavite posao. Primajte upite.'],
 ['Eine übersichtliche Website zeigt Ihre Leistungen und gibt Interessenten einen einfachen Weg zur Kontaktaufnahme. Sie wählen den Umfang, der zu Ihrem Unternehmen passt.','A clear website shows your services and gives visitors a simple way to contact you. Choose a scope that fits your business.','Un sitio claro presenta tus servicios y facilita el contacto. Elige el contenido que se adapta a tu negocio.','Un site clair présente vos services et facilite le contact. Choisissez les prestations adaptées à votre entreprise.','يعرض الموقع الواضح خدماتك ويسهّل على الزوار التواصل معك. اختر نطاقًا يناسب نشاطك.','Pregledna stranica predstavlja usluge i olakšava klijentima da vam se jave. Odaberite obim koji odgovara vašoj firmi.'], 'salon')
group('ai', ['KI-Textchat','AI text chat','Chat de texto IA','Chat textuel IA','محادثة نصية بالذكاء الاصطناعي','AI tekstualni chat'],
 ['Häufige Fragen direkt beantworten.','Answer common questions on your website.','Responde preguntas frecuentes en tu web.','Répondez aux questions fréquentes sur le site.','أجب عن الأسئلة المتكررة على الموقع.','Odgovarajte na česta pitanja na stranici.'],
 ['Ein Textassistent beantwortet freigegebene Fragen auf Ihrer Website und erfasst Kontaktdaten. Ihr Team kann die Anfrage übernehmen. Telefonanrufe gehören nicht zu diesen Paketen.','A text assistant answers approved questions on your website and captures contact details. Your team can follow up. Phone calls are not part of these packages.','Un asistente de texto responde preguntas aprobadas y recoge datos de contacto. Tu equipo puede continuar la atención. Las llamadas no forman parte de estos paquetes.','Un assistant textuel répond aux questions validées et recueille les coordonnées. Votre équipe peut prendre le relais. Les appels ne font pas partie de ces forfaits.','يجيب المساعد النصي عن الأسئلة المعتمدة ويجمع بيانات التواصل، ويمكن للفريق متابعة الطلب. المكالمات الهاتفية ليست ضمن هذه الباقات.','Tekstualni asistent odgovara prema odobrenim informacijama i prikuplja kontakt podatke. Vaš tim preuzima upit. Telefonski pozivi nisu dio ovih paketa.'], 'team')
group('automation', ['Automatisierung','Automation','Automatización','Automatisation','الأتمتة','Automatizacija'],
 ['Weniger manuelles Übertragen.','Less manual copying between tools.','Menos copiar datos a mano.','Moins de transferts manuels.','قلّل نقل البيانات يدويًا.','Manje ručnog prepisivanja.'],
 ['Wenn eine Anfrage eingeht, kann ein vereinbarter Ablauf Daten speichern, einen Status setzen und eine E-Mail-Benachrichtigung vorbereiten. So bleibt der nächste Schritt sichtbar.','When an inquiry arrives, an agreed workflow can save data, set a status and prepare an email notification. The next step stays visible.','Cuando llega una solicitud, un flujo acordado puede guardar datos, asignar un estado y preparar un aviso por correo. El siguiente paso queda claro.','À l’arrivée d’une demande, un processus convenu peut enregistrer les données, définir un statut et préparer une notification e-mail. La suite reste visible.','عند وصول طلب، يمكن لسير العمل المتفق عليه حفظ البيانات وتعيين الحالة وتجهيز إشعار بالبريد، ليبقى الإجراء التالي واضحًا.','Kad stigne upit, dogovoreni tok može spremiti podatke, postaviti status i pripremiti e-mail obavijest. Sljedeći korak ostaje pregledan.'], 'workspace')
group('company', ['Company OS','Company OS','Company OS','Company OS','Company OS','Company OS'],
 ['Anfragen und Status an einem Ort.','Keep inquiries and statuses in one place.','Solicitudes y estados en un solo lugar.','Demandes et statuts au même endroit.','الطلبات والحالات في مكان واحد.','Upiti i statusi na jednom mjestu.'],
 ['Ein geschützter Arbeitsbereich bündelt Anfragen, Terminwünsche und Ihren Leistungskatalog für ein Unternehmen. Sie sehen, was neu ist und was bearbeitet wird.','A protected workspace brings together inquiries, appointment requests and your service catalog for one business. See what is new and what is being handled.','Un espacio protegido reúne solicitudes, peticiones de cita y catálogo de servicios para una empresa. Puedes ver qué es nuevo y qué está en curso.','Un espace protégé réunit demandes, souhaits de rendez-vous et catalogue de services pour une entreprise. Voyez ce qui est nouveau ou en cours.','تجمع مساحة محمية الطلبات ورغبات المواعيد ودليل الخدمات لشركة واحدة، لتعرف ما هو جديد وما تتم معالجته.','Zaštićen radni prostor objedinjuje upite, zahtjeve za termin i katalog usluga za jednu firmu. Vidite šta je novo, a šta u obradi.'], 'team')
group('hosting', ['Hosting & Domain','Hosting & domain','Hosting y dominio','Hébergement et domaine','الاستضافة والنطاق','Hosting i domene'],
 ['Die technische Basis für Ihre Website.','The technical foundation for your website.','La base técnica de tu sitio web.','La base technique de votre site.','الأساس التقني لموقعك.','Tehnička osnova vaše stranice.'],
 ['Hosting ist der Speicher- und Betriebsplatz Ihrer Website. Eine Domain ist die Adresse, unter der Besucher Sie erreichen. Wählen Sie die Leistung passend zu Ihrer Website; die Erstellung der Website ist ein separates Paket.','Hosting provides the storage and running environment for your website. A domain is the address visitors use to reach it. Choose what your website needs; building the website is a separate package.','El hosting es el espacio y entorno donde funciona tu sitio. El dominio es su dirección. Elige lo que necesita tu web; su creación es un paquete separado.','L’hébergement fournit l’espace et l’environnement de votre site. Le domaine est son adresse. Choisissez selon vos besoins ; la création du site est un forfait séparé.','توفر الاستضافة مساحة التخزين وبيئة تشغيل الموقع، والنطاق هو عنوانه. اختر ما يحتاجه موقعك؛ إنشاء الموقع باقة منفصلة.','Hosting je prostor i okruženje u kojem radi vaša stranica. Domena je adresa preko koje je posjetioci nalaze. Izrada stranice je poseban paket.'], 'workspace')

